#include "ENGINE/Source/Os/W32/time.h"
#include <algorithm>
#include <mutex>
#include <unordered_set>
#include <cstdlib>
namespace{std::mutex s_lock;std::unordered_set<Sound*>s_sounds;float s_master=1,s_music=1,s_sound=1;bool s_muted=false;NTempest::C3Vector s_listener;unsigned s_categories[3]{};enum{F_PLAYING=1,F_STOPPING=2,F_SUSPENDED=4,F_LOOP=8,F_3D=16,F_PAUSED=32,F_FADE=64,F_UPDATE=128,F_PAN=256,F_CUTOFF=512};}
Sound::Sound():baseLink{},link{},fadeLink{},updateLink{},panningLink{},cutoffLink{},stopLink{},m_channel(-1),m_stream(nullptr),m_flags(0),m_suspendedFlags(0),m_fadeStartTime(0),m_fadeVolume(0),m_fadeRate(0),m_panning(0),m_worldPosition(),m_velocity(),m_updateHandle(0),m_cutoffDistanceSquared(0),m_volume(1),m_freq(0),m_fileNameHashed(0),m_category(SOUNDCATEGORY_NONE){}Sound::~Sound(){DecrementCategory();std::lock_guard lock(s_lock);s_sounds.erase(this);}bool Sound::Initialize(){return true;}void Sound::Shutdown(){std::lock_guard lock(s_lock);for(auto*s:s_sounds)s->m_flags=0;}Sound* Sound::Alloc(){auto*s=new(std::nothrow)Sound;if(s){std::lock_guard lock(s_lock);s_sounds.insert(s);}return s;}void Sound::KillSound(Sound*s){delete s;}
bool Sound::Play(){m_flags|=F_PLAYING;m_flags&=~(F_STOPPING|F_SUSPENDED);IncrementCategory();return true;}bool Sound::PlayLooped(){m_flags|=F_LOOP;return Play();}bool Sound::Play2D(){m_flags&=~F_3D;return Play();}bool Sound::Play2DLooped(){m_flags|=F_LOOP;return Play2D();}bool Sound::Play3D(){m_flags|=F_3D;return Play();}bool Sound::Play3DLooped(){m_flags|=F_LOOP;return Play3D();}void Sound::Stop(){m_flags&=~F_PLAYING;m_flags|=F_STOPPING;DecrementCategory();}void Sound::Suspend(){m_suspendedFlags=m_flags;m_flags|=F_SUSPENDED;}void Sound::Resume(){m_flags=m_suspendedFlags&~F_SUSPENDED;}bool Sound::IsPlaying()const{return(m_flags&F_PLAYING)!=0;}bool Sound::IsStopping()const{return(m_flags&F_STOPPING)!=0;}bool Sound::IsSuspended()const{return(m_flags&F_SUSPENDED)!=0;}bool Sound::IsOutOfRange()const{return m_cutoffDistanceSquared>0&&(m_worldPosition-s_listener).SquaredMag()>m_cutoffDistanceSquared;}float Sound::GetVolume()const{return m_volume;}unsigned Sound::GetLengthMs()const{return 0;}
void Sound::SetVolume(float v){m_volume=std::clamp(v,0.0F,1.0F);}void Sound::SetSoundVolume(float v){s_sound=std::clamp(v,0.0F,1.0F);}void Sound::SetMasterVolume(float v){s_master=std::clamp(v,0.0F,1.0F);}void Sound::SetMusicVolume(float v){s_music=std::clamp(v,0.0F,1.0F);}void Sound::SetFrequency(unsigned v){m_freq=v;}void Sound::SetPaused(bool v){if(v)m_flags|=F_PAUSED;else m_flags&=~F_PAUSED;}void Sound::SetPosition(const NTempest::C3Vector&v){m_worldPosition=v;}void Sound::SetPositionMs(unsigned){}void Sound::SetPanning(float v){if(v==-1.0F){RemoveFromPanningList();return;}m_panning=std::clamp(v,0.0F,1.0F);if(!(m_flags&F_SUSPENDED))AddToPanningList();}void Sound::SetDistances(float,float max){SetCutoffDistanceSquared(max*max);}void Sound::SetCutoffDistanceSquared(float v){m_cutoffDistanceSquared=v;AddToCutoffList();}void Sound::SetFadeIn(unsigned ms){m_fadeStartTime=OsGetAsyncTimeMs();m_fadeRate=ms?1.0F/ms:1.0F;m_fadeVolume=0;AddToFadeList();}void Sound::Set3DUpdateHandle(std::int64_t h){m_updateHandle=h;AddToUpdateList();}void Sound::UpdatePosition(){}void Sound::UpdateVolume(){if(s_muted)m_fadeVolume=0;else m_fadeVolume=int(255*m_volume*s_master*s_sound);}void Sound::UpdateSoundVolumes(){std::lock_guard lock(s_lock);for(auto*s:s_sounds)s->UpdateVolume();}
void Sound::SetListenerAttributes(const NTempest::C3Vector&p,const NTempest::C3Vector&,const NTempest::C3Vector&,const NTempest::C3Vector&){s_listener=p;}NTempest::C3Vector Sound::GetListenerPosition(){return s_listener;}void Sound::SetReverbProperties(float,float,float){}void Sound::MuteSFX(bool v){s_muted=v;}unsigned Sound::GetNumDrivers(){return 1;}const char* Sound::GetDriverName(unsigned){return "Windows default";}unsigned Sound::GetNumMixers(){return 1;}const char* Sound::GetMixerName(unsigned){return "Software";}unsigned Sound::GetNumOutputSystems(){return 1;}const char* Sound::GetOutputSystemName(unsigned){return "WinMM";}unsigned Sound::GetMixRate(){return 44100;}unsigned Sound::SndGetCPUPerformance(){return 0;}
void Sound::Update(){ProcessStopList();ProcessFadeList();ProcessCutoffList();ProcessUpdateList();ProcessPanningList();}void Sound::ProcessCutoffList(){std::lock_guard lock(s_lock);for(auto*s:s_sounds)if(s->IsOutOfRange())s->m_flags|=F_PAUSED;else s->m_flags&=~F_PAUSED;}void Sound::ProcessFadeList(){std::lock_guard lock(s_lock);for(auto*s:s_sounds)if(s->m_flags&F_FADE){float t=(OsGetAsyncTimeMs()-s->m_fadeStartTime)*s->m_fadeRate;if(t>=1)s->m_flags&=~F_FADE;s->m_fadeVolume=int(255*std::min(t,1.0F));}}void Sound::ProcessPanningList(){std::lock_guard lock(s_lock);for(auto*s:s_sounds)if(s->m_flags&F_PAN)s->m_panning=std::clamp(s->m_panning,0.0F,1.0F);}void Sound::ProcessStopList(){std::lock_guard lock(s_lock);for(auto*s:s_sounds)if(s->m_flags&F_STOPPING)s->m_flags&=~F_PLAYING;}void Sound::ProcessUpdateList(){std::lock_guard lock(s_lock);for(auto*s:s_sounds)if(s->m_flags&F_UPDATE)s->UpdatePosition();}void Sound::AddToCutoffList(){m_flags|=F_CUTOFF;}void Sound::RemoveFromCutoffList(){m_flags&=~F_CUTOFF;}void Sound::AddToFadeList(){m_flags|=F_FADE;}void Sound::RemoveFromFadeList(){m_flags&=~F_FADE;}void Sound::AddToPanningList(){m_flags|=F_PAN;}void Sound::RemoveFromPanningList(){m_flags&=~F_PAN;}void Sound::AddToUpdateList(){m_flags|=F_UPDATE;}void Sound::RemoveFromUpdateList(){m_flags&=~F_UPDATE;}void Sound::IncrementCategory(){if(m_category>0&&m_category<SOUNDCATEGORIES_NUMCATEGORIES)++s_categories[m_category];}void Sound::DecrementCategory(){if(m_category>0&&m_category<SOUNDCATEGORIES_NUMCATEGORIES&&s_categories[m_category])--s_categories[m_category];}bool Sound::DupeCheckFailed()const{return false;}void SoundIdle(){Sound::Update();}
